Section Decomp.
  Variables (nc : list Z) (msv tl wks : Z) (d : dtable).
  Hypothesis OK : build_dtable nc msv tl wks = Ok d.
  Hypothesis MSV0 : 0 <= msv.     (* [comment removed for export] *)

  Lemma build_dtable_inv :
    1 <= tl <= 12 /\ 0 <= msv <= 255 /\ FSE_BUILD_DTABLE_WKSP_SIZE tl msv <= wks /\
    exists syms1 snext hT fm syms2 position cells,
      lowprob_loop nc tl (Z.to_nat (msv + 1)) 0 (repeat None (Z.to_nat (2^tl))) [] (2^tl - 1) 1 = Ok (syms1, snext, hT, fm) /\
      ((hT = 2^tl - 1 /\ exists spread,
          spread_loop nc (Z.to_nat (msv + 1)) 0 (repeat None (Z.to_nat (2^tl + 8))) 0 = Ok spread /\
          place_loop tl (Z.to_nat (2^tl / 2)) 0 spread syms1 0 = Ok (syms2, position))
       \/ (hT <> 2^tl - 1 /\ gen_loop nc tl (Z.to_nat (msv + 1)) 0 syms1 0 hT = Ok (syms2, position) /\ position = 0)) /\
      build_loop tl (Z.to_nat (2^tl)) 0 syms2 snext [] = Ok cells /\
      d = mkDT tl fm cells.
Proof.
