Fixpoint tsym (jt : list byte) (syms : list (option Z)) : list byte :=
  match syms, jt with
  | o :: syms', b0 :: b1 :: b2 :: b3 :: jt' =>
      b0 :: b1 :: (match o with Some v => Z_to_bv 8 v | None => b2 end) :: b3 :: tsym jt' syms'
  | _, _ => jt
  end.

