Lemma tsym_cons : forall o syms b0 b1 b2 b3 jt,
  tsym (b0 :: b1 :: b2 :: b3 :: jt) (o :: syms) =
  b0 :: b1 :: (match o with Some v => Z_to_bv 8 v | None => b2 end) :: b3 :: tsym jt syms.
Proof.
