(* [comment removed for export] *)
(* [comment removed for export] *)
Fixpoint omerge (js : list byte) (sp : list (option Z)) : list byte :=
  match js, sp with
  | b :: js', o :: sp' => (match o with Some v => Z_to_bv 8 v | None => b end) :: omerge js' sp'
  | _, _ => js
  end.

